"""
补充单词释义和词根分解
"""

import json
import pandas as pd

# 1. 从 NETEM 数据补充释义
def load_netem_meanings():
    """从 NETEM 数据加载释义"""
    try:
        with open('/Users/tongterence/Desktop/xianyu/netem_vocab/netem_full_list.json', 'r', encoding='utf-8') as f:
            netem_data = json.load(f)
        
        meanings = {}
        for item in netem_data.get('5530考研词汇词频排序表', []):
            word = item.get('单词', '').lower()
            meaning = item.get('释义', '')
            if word and meaning:
                meanings[word] = meaning
        
        return meanings
    except Exception as e:
        print(f"加载 NETEM 数据失败: {e}")
        return {}

# 2. 从 Excel 补充释义
def load_excel_meanings():
    """从 Excel 加载释义"""
    try:
        df = pd.read_excel('/Users/tongterence/Desktop/xianyu/material/研究生英语/考研英语词汇-词根分类-完整例句版.xlsx')
        meanings = {}
        for _, row in df.iterrows():
            word = str(row['单词']).strip().lower()
            meaning = str(row['单词释义']).strip() if pd.notna(row['单词释义']) else ''
            if word and meaning and meaning != 'nan':
                meanings[word] = meaning
        return meanings
    except Exception as e:
        print(f"加载 Excel 数据失败: {e}")
        return {}

