# 读取现有数据
with open('data/data.json', 'r', encoding='utf-8') as f:
    data = json.load(f)

# 加载释义数据
netem_meanings = load_netem_meanings()
excel_meanings = load_excel_meanings()

# 更新单词数据
updated_meaning = 0
updated_etymology = 0

for root in data['roots']:
    for word_obj in root['words']:
        word = word_obj['word'].lower()
        
        # 补充释义
        if not word_obj.get('meaning') or word_obj['meaning'] == '':
            if word in excel_meanings:
                word_obj['meaning'] = excel_meanings[word]
                updated_meaning += 1
            elif word in netem_meanings:
                word_obj['meaning'] = netem_meanings[word]
                updated_meaning += 1
        
        # 补充词根分解
        if word in etymology_dict:
            word_obj['etymology'] = etymology_dict[word]
            updated_etymology += 1

# 保存更新后的数据
with open('data/data.json', 'w', encoding='utf-8') as f:
    json.dump(data, f, ensure_ascii=False, indent=2)

print(f"已更新 {updated_meaning} 个单词的释义")
print(f"已更新 {updated_etymology} 个单词的词根分解")

# 显示一些例子
print("\n前10个更新后的单词：")
count = 0
for root in data['roots']:
    for word in root['words']:
        if word.get('etymology'):
            print(f"  {word['word']}: {word.get('meaning', '')} | {word['etymology']}")
            count += 1
            if count >= 10:
                break
    if count >= 10:
        break
